import Foundation
struct SyncNode:Equatable {let directory:Bool;let size:UInt64;let modified:TimeInterval;var checksum:String?=nil}
struct SyncAction {let relative:String;let directory:Bool;let size:UInt64;let replacing:Bool}
enum SyncPlanner {
 static func local(_ root:String,checkpoint:()throws->Void = {})throws->[String:SyncNode]{var result=[String:SyncNode]();func scan(_ base:URL,_ relative:String,_ depth:Int=0)throws{try checkpoint();guard depth<512,result.count<100000 else{throw SFTPError.message("同步目录层级或条目数超过限制")};for file in try FileManager.default.contentsOfDirectory(at:base,includingPropertiesForKeys:[.isDirectoryKey,.isSymbolicLinkKey,.fileSizeKey,.contentModificationDateKey]){try checkpoint();guard result.count<100000 else{throw SFTPError.message("同步条目数超过限制")};let v=try file.resourceValues(forKeys:[.isDirectoryKey,.isSymbolicLinkKey,.fileSizeKey,.contentModificationDateKey]);guard v.isSymbolicLink != true else{throw SFTPError.message("同步暂不支持符号链接：\(file.path)")};let key=relative+file.lastPathComponent;result[key]=SyncNode(directory:v.isDirectory ?? false,size:UInt64(v.fileSize ?? 0),modified:v.contentModificationDate?.timeIntervalSince1970 ?? 0);if v.isDirectory==true{try scan(file,key+"/",depth+1)}}};try scan(URL(fileURLWithPath:root),"");return result}
 static func remote(_ root:String,client:RemoteFileClient)throws->[String:SyncNode]{var result=[String:SyncNode]();func scan(_ base:String,_ relative:String,_ depth:Int=0)throws{try client.checkpoint?();guard depth<512,result.count<100000 else{throw SFTPError.message("同步目录层级或条目数超过限制")};for e in try client.list(base,maximumEntries:100000-result.count){guard result.count<100000,!e.name.isEmpty,e.name != ".",e.name != "..",!e.name.contains("/"),!e.name.contains("\0") else{throw SFTPError.message("同步条目数超过限制或服务器返回无效名称")};guard e.mode&0o170000 != 0o120000 else{throw SFTPError.message("同步暂不支持符号链接：\(e.name)")};let key=relative+e.name;result[key]=SyncNode(directory:e.directory,size:e.size,modified:Double(e.modified));if e.directory{try scan((base=="/" ? "/" : base+"/")+e.name,key+"/",depth+1)}}};try scan(root,"");return result}
 static func plan(source:[String:SyncNode],target:[String:SyncNode])throws->[SyncAction]{var actions=[SyncAction]();var newDirectories=[String]();for key in source.keys.sorted(){guard let s=source[key],!newDirectories.contains(where:{key.hasPrefix($0+"/")}) else{continue};let t=target[key];if let t=t,t.directory != s.directory{throw SFTPError.message("文件与文件夹类型冲突，请先重命名或移走：\(key)")};if s.directory{if t==nil{actions.append(SyncAction(relative:key,directory:true,size:0,replacing:false));newDirectories.append(key)}else if t?.directory != true{actions.append(SyncAction(relative:key,directory:true,size:0,replacing:true))}}else if t==nil || t?.directory==true || (s.modified>(t?.modified ?? 0)+2 && (s.size != t?.size || s.modified != t?.modified)){actions.append(SyncAction(relative:key,directory:false,size:s.size,replacing:t != nil))}};return actions}
}
